UNION ALL SELECT '01' dataStatus, e.DATAUUID ASSET_UUID, e.asset_name, e.asset_code, e.asset_type, e.asset_type2, e.org_asset_type1, e.org_asset_type2, e.org_asset_type3, e.vdate vDateStr, e.mdate mDateStr, E.ERR_MSG FROM CHB_ASSET_INFO_ERRODATA e WHERE 1=1 and e.status in ('E','M')
