and 1=2
AND DATAUUID = #{Assetuuid,jdbcType=VARCHAR}
) ORDER BY dataStatus DESC

SELECT DISTINCT ASSET_CODE id, ASSET_NAME text from ( SELECT ASSET_CODE,ASSET_NAME FROM CHB_ASSET_INFO ASSETINFO
and ASSETINFO.ASSET_CODE like concat(concat('%', #{search}),'%') or ASSETINFO.ASSET_NAME like concat(concat('%', #{search}),'%')
#{orgCode,jdbcType=VARCHAR}
union all
SELECT ASSET_CODE,ASSET_NAME FROM CHB_ASSET_INFO_ERRODATA data
and data.ASSET_CODE like concat(concat('%', #{search}),'%') or data.ASSET_NAME like concat(concat('%', #{search}),'%')
#{orgCode,jdbcType=VARCHAR}
) ORDER BY ASSET_CODE

SELECT '02' dataStatus,a.*
FROM CHB_ASSET_INFO a
where ASSET_UUID = #{Assetuuid,jdbcType=VARCHAR}

SELECT * FROM SYS_DATADICT_LIST_LINK
WHERE 1=1

  and LINKED_DICT_CODE = #{linkDictCode}


  and LINKED_ITEM_CODE = #{linkItemCode}

SELECT E.CHB_ASSET_TYPE2 id, l.ITEM_VALUE text
    FROM CHB_ASSET_TYPE_MAPPING_EX E
    left join CHB_ASSET_TYPE_MAPPING M ON E.MAPPING_UUID = M.TYPEUUID
    LEFT JOIN SYS_DATADICT_LIST L ON L.DICT_CODE = 'SVR_ASSET_TYPE_SECOND_LEVEL' AND E.CHB_ASSET_TYPE2 = L.ITEM_CODE
    WHERE
        M.ASSET_TYPE1 = #{orgAssetType1}

        AND M.ASSET_TYPE2 =#{orgAssetType2}


        AND M.ASSET_TYPE3 =#{orgAssetType3}


        AND M.ASSET_BUSI_TYPE =#{orgAssetType4}


        AND (E.CHB_ASSET_TYPE2 like '%'|| #{search} ||'%'
                or l.ITEM_VALUE like '%'|| #{search} ||'%')

